<?php defined('BASEPATH') OR exit('No direct script access allowed'); ?>
<?php if($extraction_run):?><div class="card shadow-sm mb-3"><div class="card-header d-flex justify-content-between align-items-center"><h2 class="card-title mb-0">Extraction Assistance</h2><span class="badge text-bg-<?=$extraction_run->extraction_method==='ML_SERVICE'?'primary':'secondary'?>"><?=html_escape(str_replace('_',' ',$extraction_run->extraction_method))?></span></div><div class="card-body"><dl class="row mb-0"><dt class="col-sm-4">Review status</dt><dd class="col-sm-8"><?=html_escape($extraction_run->run_status)?></dd><dt class="col-sm-4">Model</dt><dd class="col-sm-8"><?=html_escape($extraction_run->model_code_snapshot?$extraction_run->model_code_snapshot.' '.$extraction_run->model_version_snapshot:'None — deterministic parser retained')?></dd><dt class="col-sm-4">Proposals</dt><dd class="col-sm-8"><?=number_format($extraction_run->prediction_count)?> · <?=number_format($extraction_run->pending_review_count)?> pending review</dd></dl><?php if($extraction_run->fallback_reason):?><div class="alert alert-info mt-3 mb-0"><?=html_escape($extraction_run->fallback_reason)?></div><?php endif;?><p class="small text-body-secondary mt-3 mb-0">The hardened parser and deterministic validation remain authoritative. ML proposals change staging only after an authorized reviewer accepts or corrects them.</p></div></div><?php endif;?>
<?php if($extraction_predictions):?><div class="card shadow-sm mb-3"><div class="card-header"><h2 class="card-title mb-0">Prediction Review</h2></div><div class="card-body"><div class="accordion" id="predictionReview"><?php foreach($extraction_predictions as$index=>$prediction):$proposal=(array)json_decode($prediction->prediction_json,TRUE);$confidence=(array)json_decode($prediction->confidence_json?:'[]',TRUE);$fields=array('item_reference'=>'Reference','section_reference'=>'Section','item_description'=>'Description','source_uom_text'=>'UOM','quantity_text'=>'Quantity','unit_rate_text'=>'Unit rate','line_amount_text'=>'Amount','notes'=>'Notes');?><div class="accordion-item"><h3 class="accordion-header"><button class="accordion-button <?=$index?'collapsed':''?>" type="button" data-bs-toggle="collapse" data-bs-target="#prediction<?=$prediction->extraction_prediction_id?>">Row <?=number_format($prediction->source_row_no)?> · <?=html_escape($prediction->prediction_status)?></button></h3><div id="prediction<?=$prediction->extraction_prediction_id?>" class="accordion-collapse collapse <?=$index?'':'show'?>" data-bs-parent="#predictionReview"><div class="accordion-body"><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Field</th><th>Current deterministic value</th><th>ML proposal</th><th>Confidence</th></tr></thead><tbody><?php foreach($fields as$field=>$label):$current_property='current_'.$field;?><tr><th><?=html_escape($label)?></th><td><?=html_escape($prediction->$current_property?:'—')?></td><td><?=html_escape(array_key_exists($field,$proposal)?($proposal[$field]===''?'(blank)':$proposal[$field]):'No change')?></td><td><?=isset($confidence[$field])?number_format($confidence[$field]*100,1).'%':'—'?></td></tr><?php endforeach;?></tbody></table></div><?php if($prediction->prediction_status==='PENDING'&&$can_review_extraction):?><?=form_open('boq/'.$boq->boq_id.'/imports/'.$batch->boq_import_batch_id.'/predictions/'.$prediction->extraction_prediction_id.'/review',array('class'=>'mt-3'))?><div class="row g-2"><?php foreach($fields as$field=>$label):$current_property='current_'.$field;$value=array_key_exists($field,$proposal)?$proposal[$field]:$prediction->$current_property;?><div class="<?=$field==='item_description'||$field==='notes'?'col-12':'col-md-6'?>"><label class="form-label" for="<?=$field?>_<?=$prediction->extraction_prediction_id?>"><?=html_escape($label)?></label><?php if($field==='item_description'||$field==='notes'):?><textarea class="form-control" id="<?=$field?>_<?=$prediction->extraction_prediction_id?>" name="<?=$field?>" rows="2"><?=html_escape($value)?></textarea><?php else:?><input class="form-control" id="<?=$field?>_<?=$prediction->extraction_prediction_id?>" name="<?=$field?>" value="<?=html_escape($value)?>"><?php endif;?></div><?php endforeach;?><div class="col-12"><label class="form-label" for="reason_<?=$prediction->extraction_prediction_id?>">Review reason</label><input class="form-control" id="reason_<?=$prediction->extraction_prediction_id?>" name="review_reason" maxlength="1000"></div><div class="col-12 d-flex gap-2"><button class="btn btn-success" name="review_action" value="accept">Accept proposal</button><button class="btn btn-primary" name="review_action" value="correct">Apply corrected fields</button><button class="btn btn-outline-danger" name="review_action" value="reject">Reject proposal</button></div></div><?=form_close()?><?php elseif($prediction->prediction_status==='PENDING'):?><div class="alert alert-warning mb-0">BOQ management and ML review permissions are both required.</div><?php endif;?></div></div></div><?php endforeach;?></div></div></div><?php endif;?>
<?php if($batch->source_sheet||$batch->parsed_line_total!==NULL):?><div class="card shadow-sm mb-3"><div class="card-header"><h2 class="card-title mb-0">Workbook Normalization</h2></div><div class="card-body"><dl class="row mb-0"><dt class="col-sm-4">Selected worksheet</dt><dd class="col-sm-8"><?=html_escape($batch->source_sheet?:'—')?></dd><dt class="col-sm-4">Parsed priced-line total</dt><dd class="col-sm-8"><?=$batch->parsed_line_total!==NULL?number_format($batch->parsed_line_total,2):'—'?></dd><dt class="col-sm-4">Source declared total</dt><dd class="col-sm-8"><?=$batch->source_declared_total!==NULL?number_format($batch->source_declared_total,2):'—'?></dd><dt class="col-sm-4">Variance</dt><dd class="col-sm-8"><?=$batch->total_variance!==NULL?number_format($batch->total_variance,2):'—'?></dd><dt class="col-sm-4">Unpriced lines</dt><dd class="col-sm-8"><?=number_format($batch->unpriced_rows)?></dd></dl><?php $material_variance=$batch->total_variance!==NULL&&abs((float)$batch->total_variance)>max(1.00,((int)$batch->total_rows)*0.01);if($material_variance):?><div class="alert alert-warning mt-3 mb-0">The parsed priced-line total differs from the workbook's declared total by <?=number_format(abs($batch->total_variance),2)?>. Review the source before committing.</div><?php endif;?><?php if($batch->normalization_notes):?><p class="small text-body-secondary mt-3 mb-0"><?=html_escape($batch->normalization_notes)?></p><?php endif;?></div></div><?php endif;?>
<div class="row g-3 mb-3"><div class="col-md-8"><div class="card shadow-sm h-100"><div class="card-body"><dl class="row mb-0"><dt class="col-4">File</dt><dd class="col-8"><?=html_escape($batch->original_file_name)?></dd><dt class="col-4">Status</dt><dd class="col-8"><?=html_escape($batch->import_status)?></dd><dt class="col-4">Rows</dt><dd class="col-8"><?=$batch->total_rows?> total · <?=$batch->valid_rows?> valid · <?=$batch->invalid_rows?> invalid</dd></dl></div></div></div><div class="col-md-4"><div class="card shadow-sm h-100"><div class="card-body"><?php if($can_manage&&$batch->import_status==='READY'&&(!$extraction_run||(int)$extraction_run->pending_review_count===0)):?><?=form_open('boq/'.$boq->boq_id.'/imports/'.$batch->boq_import_batch_id.'/commit')?><button class="btn btn-success w-100">Import Validated Rows</button><?=form_close()?><?php elseif($extraction_run&&(int)$extraction_run->pending_review_count>0):?><div class="alert alert-warning mb-0">Review all extraction proposals before importing.</div><?php elseif($batch->import_status==='INVALID'):?><div class="alert alert-warning mb-0">Correct the errors and upload a new batch.</div><?php endif;?><a class="btn btn-outline-secondary w-100 mt-2" href="<?=site_url('boq/'.$boq->boq_id)?>">Back to BOQ</a></div></div></div></div>
<div class="card shadow-sm"><div class="card-header"><h2 class="card-title mb-0">Validation Report</h2></div><div class="card-body"><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Sheet / Row</th><th>Reference</th><th>Description</th><th>UOM</th><th>Quantity</th><th>Rate</th><th>Amount</th><th>Status</th><th>Errors</th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><?=html_escape(($r->source_sheet?:'CSV').' / '.$r->source_row_no)?></td><td><?=html_escape($r->item_reference?:'—')?></td><td><?=html_escape($r->item_description?:'—')?></td><td><?=html_escape($r->source_uom_text?:'—')?></td><td><?=html_escape($r->quantity_text?:'—')?></td><td><?=html_escape($r->unit_rate_text?:'—')?></td><td><?=html_escape($r->line_amount_text?:'—')?></td><td><span class="badge text-bg-<?=$r->validation_status==='VALID'||$r->validation_status==='IMPORTED'?'success':'danger'?>"><?=html_escape($r->validation_status)?></span></td><td><?php foreach((array)json_decode($r->validation_errors?:'[]',TRUE)as$e):?><div><?=html_escape($e)?></div><?php endforeach;?></td></tr><?php endforeach;?></tbody></table></div></div></div>
